///  FlatSQL Batch Metadata: one per feed per commit round.
class FMB {
  FMB._(this._bc, this._bcOffset);
  factory FMB(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<FMB> reader = _FMBReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Stream offset of this frame's size prefix.
  int get SELF_OFFSET => const fb.Uint64Reader().vTableGet(_bc, _bcOffset, 4, 0);
  int get selfOffset => SELF_OFFSET;
  ///  Stream offset of the previous non-record frame (the commit chain).
  int get PREVIOUS => const fb.Uint64Reader().vTableGet(_bc, _bcOffset, 6, 0);
  ///  The feed's id in its type.
  int get FEED_ID => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 8, 0);
  int get feedId => FEED_ID;
  ///  The round's clock (Unix seconds).
  int get COMMITTED_AT => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 10, 0);
  int get committedAt => COMMITTED_AT;
  ///  The type's highest seq issued so far.
  int get TYPE_SEQ_HIGH => const fb.Uint64Reader().vTableGet(_bc, _bcOffset, 12, 0);
  int get typeSeqHigh => TYPE_SEQ_HIGH;
  ///  The rows, in plan order; at most 65,536.
  List<FMBRow>? get ROWS => const fb.ListReader<FMBRow>(FMBRow.reader).vTableGetNullable(_bc, _bcOffset, 14);
  ///  sha2-256 of the record bytes, 32 bytes per NEW_FRAME row, in row order
  ///  (for a sealed row, the plaintext's: its record CID).
  List<int>? get DIGESTS => const fb.Uint8ListReader().vTableGetNullable(_bc, _bcOffset, 16);
  List<FMBGroup>? get GROUPS => const fb.ListReader<FMBGroup>(FMBGroup.reader).vTableGetNullable(_bc, _bcOffset, 18);
  List<FMBEntry>? get DICTIONARY => const fb.ListReader<FMBEntry>(FMBEntry.reader).vTableGetNullable(_bc, _bcOffset, 20);
  List<FMBRemove>? get REMOVALS => const fb.ListReader<FMBRemove>(FMBRemove.reader).vTableGetNullable(_bc, _bcOffset, 22);
  List<FMBUrl>? get URLS => const fb.ListReader<FMBUrl>(FMBUrl.reader).vTableGetNullable(_bc, _bcOffset, 24);
  List<FMBSignature>? get SIGNATURES => const fb.ListReader<FMBSignature>(FMBSignature.reader).vTableGetNullable(_bc, _bcOffset, 26);
  List<FMBSealed>? get SEALED => const fb.ListReader<FMBSealed>(FMBSealed.reader).vTableGetNullable(_bc, _bcOffset, 28);
  List<FMBIdentity>? get IDENTITIES => const fb.ListReader<FMBIdentity>(FMBIdentity.reader).vTableGetNullable(_bc, _bcOffset, 30);
  List<FMBLarge>? get LARGE => const fb.ListReader<FMBLarge>(FMBLarge.reader).vTableGetNullable(_bc, _bcOffset, 32);

  @override
  String toString() {
    return 'FMB{selfOffset: ${selfOffset}, PREVIOUS: ${PREVIOUS}, feedId: ${feedId}, committedAt: ${committedAt}, typeSeqHigh: ${typeSeqHigh}, ROWS: ${ROWS}, DIGESTS: ${DIGESTS}, GROUPS: ${GROUPS}, DICTIONARY: ${DICTIONARY}, REMOVALS: ${REMOVALS}, URLS: ${URLS}, SIGNATURES: ${SIGNATURES}, SEALED: ${SEALED}, IDENTITIES: ${IDENTITIES}, LARGE: ${LARGE}}';
  }
}

